import { openDatabase } from '@qb-flex/database';
const db = openDatabase(process.argv[2]!);
await db.exec(
  'CREATE TABLE ledger(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,value TEXT NOT NULL)',
);
for (let i = 1; i <= 20; i++) {
  await db.query('INSERT INTO ledger VALUES(?,?)').run(i, 'acknowledged');
  console.log('ACK ' + i);
}
await db.exec("BEGIN;INSERT INTO ledger VALUES(21,'uncommitted');");
console.log('UNCOMMITTED');
await new Promise(() => {});
